// Bundled original Open Doodles SVGs by Pablo Stanley (CC0). See editorial-illustrations/PROVENANCE.md.
const SVG_DATA = Object.freeze({
  "doodles-loving": "data:image/svg+xml;base64,",
  "doodles-dancing": "data:image/svg+xml;base64,",
  "doodles-reading": "data:image/svg+xml;base64,",
  "doodles-petting": "data:image/svg+xml;base64,",
  "doodles-unboxing": "data:image/svg+xml;base64,",
  "doodles-running": "data:image/svg+xml;base64,",
  "doodles-coffee": "data:image/svg+xml;base64,",
  "doodles-selfie": "data:image/svg+xml;base64,",
  "doodles-meditating": "data:image/svg+xml;base64,",
  "doodles-strolling": "data:image/svg+xml;base64,",
});

const DEFINITIONS = [
  { illustrationId: "doodles-loving", alt: "Hand-drawn person holding a heart", terms: ["relationship", "relationships", "love", "family", "friend", "friends", "friendship", "supporting", "care", "caring", "support", "belonging", "kindness", "heart"] },
  { illustrationId: "doodles-dancing", alt: "Hand-drawn person dancing to music", terms: ["music", "song", "singing", "sound", "audio", "dance", "dancing", "rhythm", "concert", "album", "band", "melody", "playlist"] },
  { illustrationId: "doodles-reading", alt: "Hand-drawn person reading a book", terms: ["learn", "learning", "education", "reading", "book", "study", "school", "teaching", "research", "knowledge", "guide"] },
  { illustrationId: "doodles-petting", alt: "Hand-drawn person caring for a dog", terms: ["pet", "pets", "dog", "animal", "companion", "companionship", "community", "care", "caring", "nurture"] },
  { illustrationId: "doodles-unboxing", alt: "Hand-drawn person emerging from a box", terms: ["craft", "create", "making", "build", "building", "design", "creative", "maker", "project", "launch", "invent", "idea"] },
  { illustrationId: "doodles-running", alt: "Hand-drawn person running", terms: ["run", "running", "sport", "fitness", "exercise", "movement", "walking", "travel", "journey", "cycling", "physical"] },
  { illustrationId: "doodles-coffee", alt: "Hand-drawn person hugging a coffee cup", terms: ["work", "working", "job", "career", "office", "business", "break", "rest", "coffee", "workplace"] },
  { illustrationId: "doodles-selfie", alt: "Hand-drawn person taking a selfie", terms: ["share", "sharing", "social", "photo", "photography", "identity", "portrait", "camera", "media"] },
  { illustrationId: "doodles-meditating", alt: "Hand-drawn person meditating", terms: ["health", "wellbeing", "wellness", "mind", "mental", "calm", "peace", "meditation", "stress", "reflection"] },
  { illustrationId: "doodles-strolling", alt: "Hand-drawn person strolling", terms: [] },
];

const CREDIT = "Illustration by Pablo Stanley · Open Doodles (CC0)";
const CREDIT_URL = "https://www.opendoodles.com/about";
export const EDITORIAL_ILLUSTRATIONS = Object.freeze(DEFINITIONS.map(({ illustrationId, alt }) => Object.freeze({
  illustrationId, kind: "illustration", externalUrl: SVG_DATA[illustrationId], alt, href: CREDIT_URL, label: CREDIT, mode: "cinema", focalPoint: "center", license: "CC0",
})));
const BY_ID = Object.freeze(Object.fromEntries(EDITORIAL_ILLUSTRATIONS.map((media) => [media.illustrationId, media])));

export function illustrationById(id) {
  return typeof id === "string" && Object.hasOwn(BY_ID, id) ? BY_ID[id] : null;
}

function words(value) {
  return new Set(String(value ?? "").toLowerCase().match(/[\p{L}\p{N}]+/gu) ?? []);
}

export function illustrationForChunk(chunk) {
  const title = words(chunk?.title);
  const body = words(chunk?.markdown ?? chunk?.body ?? chunk?.summary);
  const kind = words(chunk?.kind);
  let best = null;
  let bestScore = 0;
  for (const definition of DEFINITIONS) {
    if (definition.illustrationId === "doodles-strolling") continue;
    const score = definition.terms.reduce((total, term) => total + (title.has(term) ? 4 : 0) + (body.has(term) ? 1 : 0) + (kind.has(term) ? 3 : 0), 0);
    if (score > bestScore) { bestScore = score; best = definition.illustrationId; }
  }
  return illustrationById(best ?? "doodles-strolling");
}
